mapper.select:
SELECT DATE_FORMAT( `collect_time`, '%Y-%m-%d') `recordTime` FROM `power_distribution_box` where `statistical_method` = 'ELECTRICITY'
and `collect_time` between #{startTime} and #{endTime}
GROUP BY `recordTime` ORDER BY `recordTime` DESC

SELECT DATE_FORMAT( `collect_time`, '%Y-%m-%d') `recordTime` FROM `power_distribution_box` where `statistical_method` = 'ELECTRICITY'
and `collect_time` between #{startTime} and #{endTime}
GROUP BY `recordTime` ORDER BY `recordTime` DESC

SELECT to_char( `collect_time`, 'yyyy-MM-dd') `recordTime` FROM `power_distribution_box` where `statistical_method` = 'ELECTRICITY'
and `collect_time` between #{startTime} and #{endTime}
GROUP BY `recordTime` ORDER BY `recordTime` DESC

SELECT DATE_FORMAT( a.`collect_time`, '%Y-%m-%d') `recordTime`,a.`device_id` `deviceId`,b.`high_distribution_name` `deviceName` FROM `power_distribution_box` a left join `transformer_distribution` b on a.`device_id` = b.`high_distribution` where a.`statistical_method` = 'DISTRIBUTION'
and a.`collect_time` between #{startTime} and #{endTime}
GROUP BY `recordTime`,`deviceName` ORDER BY `recordTime` DESC

SELECT DATE_FORMAT( a.`collect_time`, '%Y-%m-%d') `recordTime`,a.`device_id` `deviceId`,b.`high_distribution_name` `deviceName` FROM `power_distribution_box` a left join `transformer_distribution` b on a.`device_id` = b.`high_distribution` where a.`statistical_method` = 'DISTRIBUTION'
and a.`collect_time` between #{startTime} and #{endTime}
GROUP BY `recordTime`,`deviceName` ORDER BY `recordTime` DESC

